// TripServiceServer is the server API for TripService service.
// All implementations must embed UnimplementedTripServiceServer
// for forward compatibility.
type TripServiceServer interface {
	RequestTrip(context.Context, *RequestTripRequest) (*RequestTripResponse, error)
	AcceptTrip(context.Context, *AcceptTripRequest) (*AcceptTripResponse, error)
	// MarkDriverArrived is the driver telling the rider they are at the
	// pickup. Only while the trip is accepted, and only within 200 metres of
	// the pickup by the driver's last reported position. Waiting time (and
	// the rider no-show) counts from here. Marking again changes nothing.
	MarkDriverArrived(context.Context, *MarkDriverArrivedRequest) (*MarkDriverArrivedResponse, error)
	// ReachStop is the driver telling the rider they are at one of the trip's
	// stops (position 1 is the first). Only while the trip is in progress, and
	// within 200 metres of the stop by the driver's last reported position.
	// Any stop not reached yet may be marked: the rider may skip one. Marking a
	// reached stop again changes nothing.
	ReachStop(context.Context, *ReachStopRequest) (*ReachStopResponse, error)
	StartTrip(context.Context, *StartTripRequest) (*StartTripResponse, error)
	CompleteTrip(context.Context, *CompleteTripRequest) (*CompleteTripResponse, error)
	CancelTrip(context.Context, *CancelTripRequest) (*CancelTripResponse, error)
	// GetTrip is the rider/driver app's poll target for live trip status —
	// both the Rider app's tracking screen and the Driver app's active-trip
	// screen call this every few seconds until they see the status they're
	// waiting for (ACCEPTED, then IN_PROGRESS, then COMPLETED).
	GetTrip(context.Context, *GetTripRequest) (*GetTripResponse, error)
	// TriggerSOS records a safety alert during an active trip — it does
	// NOT replace calling emergency services directly (the app's SOS
	// button dials the local emergency number itself); this is the
	// platform-side record: what trip, who pressed it, and where, so the
	// safety team can pull up the trip (and its path, via GetTripPath)
	// immediately and a notification goes out to the configured safety
	// contact.
	TriggerSOS(context.Context, *TriggerSOSRequest) (*TriggerSOSResponse, error)
	// RecordWaypoint appends one point to the trip's path. Called by the
	// driver app on a timer (every ~15-30s) alongside — not instead of —
	// its regular LocationService.UpdateLocation ping; the two are
	// independent so a failure in one never blocks the other. Duplicate
	// calls inside the throttle window are silently absorbed, so the
	// caller doesn't need its own client-side timing logic.
	RecordWaypoint(context.Context, *RecordWaypointRequest) (*RecordWaypointResponse, error)
	// GetTripPath returns every waypoint recorded for a trip, oldest
	// first — the reconstructed route for a completed trip, or the route
	// so far for one still in progress (e.g. right after an SOS alert).
	GetTripPath(context.Context, *GetTripPathRequest) (*GetTripPathResponse, error)
	// GetDriverLocation is the Rider app's live-tracking poll target: where the
	// driver of this trip last reported being. Only the trip's rider may ask, and
	// only while the trip is ACCEPTED or IN_PROGRESS (FAILED_PRECONDITION
	// otherwise). It returns the position and when the driver reported it, and
	// nothing else about the driver. NOT_FOUND means the driver has not reported
	// recently (a live position expires after 30 seconds); the app keeps polling.
	GetDriverLocation(context.Context, *GetDriverLocationRequest) (*GetDriverLocationResponse, error)
	// GetTripDriver is how the rider's app shows who is driving: the driver's name, car,
	// plate and rating. Only the rider of the trip may ask, and only once a driver has
	// accepted (FAILED_PRECONDITION before that). It has no phone number, no identity and
	// nothing about the driver's account.
	GetTripDriver(context.Context, *GetTripDriverRequest) (*GetTripDriverResponse, error)
	// GetActiveTrip is how an app finds the trip it should be showing: the caller's
	// requested, accepted or in-progress trip, for example when the app is opened
	// again after being closed. Name exactly one of rider_id and driver_id, and it
	// must be the caller's own profile. NOT_FOUND means there is no active trip.
	GetActiveTrip(context.Context, *GetActiveTripRequest) (*GetActiveTripResponse, error)
	// ListTrips is the caller's trip history, newest first, one page at a time. Name
	// exactly one of rider_id and driver_id, and it must be the caller's own profile.
	// Pass the previous page's next_page_token to get the following page; an empty
	// next_page_token means that was the last one.
	ListTrips(context.Context, *ListTripsRequest) (*ListTripsResponse, error)
	// OfferTrip puts a trip to one driver for a short time: ttl_seconds (default 15,
	// clamped to 5-60). Internal: only dispatch calls it. A driver is offered a trip
	// at most once, so dispatch needs no memory of who it already asked. The refusals
	// tell dispatch what to do: ALREADY_EXISTS (this driver was offered it before)
	// and FAILED_PRECONDITION (the driver has a pending offer or a trip, or the trip
	// is no longer waiting) mean try the next driver; ABORTED means another driver
	// has a live offer for this trip, so wait for it to be answered or to expire.
	OfferTrip(context.Context, *OfferTripRequest) (*OfferTripResponse, error)
	// GetPendingOffer is the Driver app's poll target: the trip it is being offered,
	// with what it needs to decide (where from and to, vehicle class, payment method,
	// when the offer ends), or NOT_FOUND when there is none. It does not say who the
	// rider is. driver_id must be the caller's own driver profile.
	GetPendingOffer(context.Context, *GetPendingOfferRequest) (*GetPendingOfferResponse, error)
	// AcceptOffer makes the caller the driver of the trip: the offer and the trip
	// change together (the trip goes from REQUESTED to ACCEPTED). NOT_FOUND: there
	// is no live offer of this trip to this driver. FAILED_PRECONDITION: the offer
	// expired, the trip was cancelled meanwhile, or the driver is on another trip.
	// driver_id must be the caller's own driver profile.
	AcceptOffer(context.Context, *AcceptOfferRequest) (*AcceptOfferResponse, error)
	// RejectOffer declines the offer; the trip goes on to the next driver, and this
	// driver is not offered it again. driver_id must be the caller's own profile.
	RejectOffer(context.Context, *RejectOfferRequest) (*RejectOfferResponse, error)
	// GetPickupPhoto gives a short-lived link to the photo of the saved pickup
	// address, to the rider and the driver of the trip while it is accepted or
	// in progress.
	GetPickupPhoto(context.Context, *GetPickupPhotoRequest) (*GetPickupPhotoResponse, error)
	// ListRecentDestinations lists where the rider's completed trips ended,
	// most recent first, each place once.
	ListRecentDestinations(context.Context, *ListRecentDestinationsRequest) (*ListRecentDestinationsResponse, error)
	// RateTrip is how one side rates the other after a trip: the rider rates the driver and
	// the driver rates the rider. rated_by names who is speaking and must be the caller's
	// own side of that trip. Only a COMPLETED trip, within 24 hours of completing, once per
	// side (ALREADY_EXISTS the second time, which an app can treat as done). Stars are whole
	// numbers from 1 to 5; the comment is optional (500 characters at most) and is kept for
	// the operating company only: the person rated never sees it.
	RateTrip(context.Context, *RateTripRequest) (*RateTripResponse, error)
	// Scheduled trips: a rider books a trip for later (30 minutes to 7 days
	// ahead, at most 3 upcoming). It becomes a real trip, with the same id,
	// 10 minutes before the time and is dispatched like any other; if it
	// cannot be then (say the rider is on another trip) it is tried again
	// until 10 minutes after the time, then it fails. It is priced when it
	// completes, like a trip without a quote.
	ScheduleTrip(context.Context, *ScheduleTripRequest) (*ScheduledTripResponse, error)
	// ListScheduledTrips: the rider's upcoming ones, soonest first (with
	// include_past, the latest 50 of any status, newest first).
	ListScheduledTrips(context.Context, *ListScheduledTripsRequest) (*ListScheduledTripsResponse, error)
	// CancelScheduledTrip cancels one not dispatched yet, free.
	CancelScheduledTrip(context.Context, *CancelScheduledTripRequest) (*ScheduledTripResponse, error)
	// Sharing a trip. ShareTrip makes a link the rider sends to people they
	// trust: only the trip's rider, only while the trip is under way, at most
	// 5 live links per trip. The token is returned once and only its hash is
	// kept. StopSharingTrip ends every link to the trip.
	ShareTrip(context.Context, *ShareTripRequest) (*ShareTripResponse, error)
	StopSharingTrip(context.Context, *StopSharingTripRequest) (*StopSharingTripResponse, error)
	// GetSharedTrip is what a link shows, to anyone who has it and without an
	// account: the trip's status and route, the driver's name and car, and
	// their position while the trip is under way. Never who the rider is, the
	// price or a phone number. NOT_FOUND once the link was stopped, expired, or
	// its trip ended more than TRIP_SHARE_AFTER_END ago.
	GetSharedTrip(context.Context, *GetSharedTripRequest) (*GetSharedTripResponse, error)
	mustEmbedUnimplementedTripServiceServer()
}

